window.THRANTIR_DATA={"characters": [{"id": "lucien", "name": "Lucien Vhaar", "type": "PG", "image": "assets/characters/lucien_thrantir.png", "subtitle": "Bardo • Oceano", "tags": ["Party", "PG", "Oceano"], "text": "Veleggiante originario di Oceano. Musicista, recuperatore di DAM e improvvisato tecnico dell’Era Atomica. Sopravvissuto alla distruzione del proprio mondo e allo schianto su Thrantir.", "status": "A bordo della Nostromo. Ultima azione documentata: prepararsi a ripulire il sistema della spelljammer catturata per cancellare i legami con Kethara.", "known": "Canonico: Background + Riassunto + documenti personali."}, {"id": "xarion", "name": "Xarion Reed", "type": "PG", "image": "assets/characters/xarion.jpg", "subtitle": "Compagno • navigatore/tecnico", "tags": ["Party", "PG"], "text": "Compagno di Lucien fin dall’atterraggio su Thrantir. Ha interagito profondamente con l’elmo della Nostromo, arrivando a percepire segnali e navi attraverso di essa.", "status": "Sulla Nostromo. Ha individuato due droni Resheph e una spelljammer dei Figli dell’Orizzonte in avvicinamento.", "known": "Canonico dal Riassunto."}, {"id": "dregan", "name": "Dregan", "type": "PG", "image": "assets/characters/dregan.jpg", "subtitle": "Compagno • tattico", "tags": ["Party", "PG"], "text": "Membro del gruppo, pragmatico e incline a soluzioni dirette. Ha proposto di trasformare la Nostromo in un labirinto controllato durante l’abbordaggio.", "status": "Ha ucciso il capitano nemico durante l’imboscata e negoziato la resa dei tre superstiti.", "known": "Canonico dal Riassunto."}, {"id": "marcus", "name": "Marcus Shamrock", "type": "PG", "image": "assets/characters/marcus.jpg", "subtitle": "Compagno • legame con Otto", "tags": ["Party", "PG"], "text": "Membro del gruppo. Ha rivelato il proprio rapporto con un baatezu che chiama Otto von Sieg Hail, legato alle coordinate sull’Oron Esgail.", "status": "Sulla Nostromo.", "known": "Canonico dal Riassunto."}, {"id": "vael", "name": "Fratello Vael", "type": "NPC", "image": "assets/characters/vael.jpg", "subtitle": "Figura religiosa • Figli dell’Orizzonte", "tags": ["NPC", "Figli dell’Orizzonte"], "text": "Figura centrale nel rapporto del gruppo con i Figli dell’Orizzonte. Lucien lo ha proclamato, senza consenso, araldo dell’Occhio del Creatore durante l’incursione nelle reti di Kethara.", "status": "Ha avvertito Lucien che il falso messaggio potrebbe causare scisma, purghe e condanne, rendendo chiunque gli sia vicino un bersaglio prioritario.", "known": "Canonico dal Riassunto."}, {"id": "loox", "name": "Loox", "type": "NPC", "image": "assets/characters/loox.png", "subtitle": "Alleato • “araldo” scenico", "tags": ["NPC", "Alleato"], "text": "Creatura/alleato usato da Lucien durante l’abbordaggio come manifestazione scenica dell’autorità di Vael e dell’Occhio del Creatore.", "status": "Presente sulla Nostromo durante l’imboscata.", "known": "Canonico dal Riassunto; reference AI Art."}], "places": [{"id": "thrantir", "name": "Thrantir", "kind": "Mondo", "image": "assets/characters/lucien_thrantir.png", "text": "Pianeta madre devastato. Il cielo come un tempo non esiste più; sopra il mondo domina l’astro oscuro identificato religiosamente come Occhio del Creatore.", "x": 48, "y": 43}, {"id": "itoigawa", "name": "Itoigawa", "kind": "Insediamento", "image": "assets/places/ramo_discendente.jpg", "text": "Piccola baraccopoli di alcune migliaia di abitanti sviluppata sulla mesa e costruita in gran parte con materiali di recupero. È secca, polverosa e priva di acqua libera visibile: l’acqua decontaminata è razionata e controllata dai Figli dell’Orizzonte.", "x": 34, "y": 62}, {"id": "kethara", "name": "Kethara", "kind": "Cittadella", "image": null, "text": "Kethara non è ancora stata visitata dal gruppo. Lucien ne ha ricostruito soltanto la topologia dei server/rete in anelli concentrici: non va trattata come una mappa urbana verificata.", "x": 70, "y": 30}, {"id": "nostromo", "name": "La Nostromo", "kind": "Spelljammer", "image": "assets/ships/nostromo_plan.png", "text": "Spelljammer utilizzata dal gruppo come base. La nave dispone di sistemi controllabili, gravità locale, porte e infrastrutture dell’Era Atomica.", "x": 56, "y": 65}, {"id": "ramo", "name": "Il Ramo Discendente", "kind": "Taverna", "image": "assets/places/ramo_discendente.jpg", "text": "Taverna di Itoigawa, uno dei primi punti di incontro del gruppo.", "x": 30, "y": 68}, {"id": "oceano", "name": "Oceano", "kind": "Mondo/colonia", "image": "assets/characters/lucien_oceano.png", "text": "Pianeta interamente oceanico e patria di Lucien. Colonia dell’Impero Atomico, con Abitatori del Profondo e Veleggianti. Il mondo viene attaccato dall’Orda e Lucien fugge poco prima della catastrofe.", "x": 12, "y": 18}], "timeline": [{"title": "Oceano — prima di Thrantir", "text": "Lucien cresce nella Cupola Cinque, diventa musicista e collezionista di DAM; dopo il crollo del tunnel LV-426 perde i genitori e diventa Veleggiante."}, {"title": "Fuga da Oceano", "text": "La spelljammer di Lucien esegue la sequenza di rientro verso Thrantir mentre l’Orda attacca Oceano."}, {"title": "Sessione 0 — Atterraggio su Thrantir", "text": "Lucien e Xarion precipitano e vengono recuperati da pellegrini nel deserto."}, {"title": "Itoigawa", "text": "Il gruppo prende forma e scopre il controllo dei Figli dell’Orizzonte su acqua, tributi e tecnologia."}, {"title": "Nostromo / Promiscuous Mode", "text": "Lucien intercetta il traffico di Kethara e trasmette un falso messaggio religioso, proclamando Vael araldo dell’Occhio del Creatore."}, {"title": "Conseguenze", "text": "Vael descrive il rischio di scisma, purghe e caccia ai presunti seguaci. La posizione del gruppo diventa molto più pericolosa."}, {"title": "Abbording della Nostromo", "text": "Xarion rileva due droni Resheph e una spelljammer. Il gruppo resta a bordo, prepara un labirinto e tende un’imboscata."}, {"title": "Situazione attuale", "text": "Capitano nemico ucciso; tre Fratelli si arrendono. Lucien inganna Kethara facendo risultare la nave catturata in rientro d’emergenza e si prepara a ripulirne il sistema."}], "mysteries": [{"name": "L’Occhio del Creatore", "state": "APERTO", "text": "Divinità dei Figli dell’Orizzonte, manifestata come buco nero. Natura religiosa e natura cosmologica non vanno confuse."}, {"name": "Voce nella rete", "state": "APERTO", "text": "Durante Promiscuous Mode Lucien riceve una trasmissione senza intestazione che gli dice di vivere/scrivere la storia."}, {"name": "Oron Esgail", "state": "APERTO", "text": "Coordinate associate al messaggio ricevuto da Marcus/Otto e a fenomeni percepiti da Xarion."}, {"name": "Otto von Sieg Hail", "state": "APERTO", "text": "Baatezu legato a Marcus; sostiene che raggiungere le coordinate sia necessario per sopravvivere."}, {"name": "Resheph", "state": "IDENTIFICATO", "text": "Drone ad alta energia dei Figli dell’Orizzonte: agile, resistente, immune a veleno/connessioni psioniche e capace di autodistruzione."}]};
window.THRANTIR_REPLAY=[{"id": "bg-oceano", "chapter": "BG", "title": "Cupola Cinque — Oceano", "place": "Oceano", "image": "assets/characters/lucien_oceano.png", "duration": 12, "summary": "Lucien cresce nel distretto dei manutentori della Cupola Cinque. Rifiuta la strada del padre Darios, si improvvisa musicista e colleziona DAM.", "dialogue": [{"speaker": "Lucien", "kind": "RECONSTRUCTION", "text": "La musica almeno mi porta fuori da qui."}], "cast": ["lucien"], "canon": "Background"}, {"id": "bg-lv426", "chapter": "BG", "title": "Il crollo del tunnel LV-426", "place": "Oceano", "image": "assets/characters/lucien_oceano.png", "duration": 10, "summary": "Il tunnel LV-426 crolla. Lucien è l’unico superstite e perde i genitori. Abbandona le profondità e raggiunge i vecchi moli.", "dialogue": [{"speaker": "Lucien", "kind": "CANONICO", "text": "Cosa avrebbe fatto Dutch Schaefer al mio posto?"}], "cast": ["lucien"], "canon": "Background"}, {"id": "bg-spelljammer", "chapter": "BG", "title": "Il Veleggiante", "place": "Oceano", "image": "assets/characters/lucien_oceano.png", "duration": 12, "summary": "Lucien sgancia una vecchia spelljammer dalla cittadella sommersa e sfrutta la spinta dell’acqua per tornare in superficie. La converte poi in nave da superficie.", "dialogue": [], "cast": ["lucien"], "canon": "Background"}, {"id": "bg-fuga", "chapter": "BG", "title": "Fuga da Oceano", "place": "Oceano", "image": "assets/characters/lucien_oceano.png", "duration": 11, "summary": "Mentre l’Orda devasta Oceano, la vecchia sequenza di rientro forza la rotta verso Thrantir. Lucien ordina una partenza d’emergenza.", "dialogue": [{"speaker": "Lucien", "kind": "CANONICO", "text": "Parti stupida troia! Questa è una fottuta emergenza!"}, {"speaker": "Nave", "kind": "CANONICO", "text": "Partenza d’emergenza attivata!"}], "cast": ["lucien"], "canon": "Background / Sessione 0"}, {"id": "s0-deserto", "chapter": "S0", "title": "Sopravvissuti nel deserto", "place": "Thrantir", "image": "assets/characters/lucien_thrantir.png", "duration": 14, "summary": "Lucien e Xarion riprendono conoscenza su travois trascinati da pellegrini. Entrambi sono sopravvissuti allo schianto.", "dialogue": [{"speaker": "Lucien", "kind": "CANONICO", "text": "Ho chiesto perché questi trabiccoli avessero delle lame per fendere la sabbia. Mi hanno dato un pugno e sono tornati a trascinarci."}, {"speaker": "Xarion", "kind": "CANONICO", "text": "E perché hai chiesto una cosa così stupida!?"}, {"speaker": "Lucien", "kind": "CANONICO", "text": "Perché… Tu conosci la risposta?"}], "cast": ["lucien", "xarion"], "canon": "Sessione 0 / Riassunto"}, {"id": "s1-occhio", "chapter": "S1", "title": "Il cielo spezzato", "place": "Thrantir", "image": "assets/characters/lucien_thrantir.png", "duration": 13, "summary": "Il sole è scomparso. Un astro oscuro domina il cielo e l’universo sembra convergere verso il buco nero.", "dialogue": [{"speaker": "Lucien", "kind": "CANONICO", "text": "Vedi, quello che stiamo osservando, è un buco nero!"}, {"speaker": "Xarion", "kind": "CANONICO", "text": "Quello era Matthew McConaughey! E il film era Interstellar!!!"}], "cast": ["lucien", "xarion"], "canon": "Riassunto 19/06/2026"}, {"id": "s1-itoigawa", "chapter": "S1", "title": "Ingresso a Itoigawa", "place": "Itoigawa", "image": "assets/places/ramo_discendente.jpg", "duration": 14, "summary": "I superstiti raggiungono la mesa. Scoprono tributi, razionamento dell’acqua e il simbolo dei Figli dell’Orizzonte.", "dialogue": [{"speaker": "Fagus", "kind": "CANONICO", "text": "Ti suggerisco di nascondere il contenuto della tua borsa, ragazzo mio."}], "cast": ["lucien", "xarion"], "canon": "Riassunto 19/06/2026"}, {"id": "s1-ramo", "chapter": "S1", "title": "Il Ramo Discendente", "place": "Itoigawa", "image": "assets/places/ramo_discendente.jpg", "duration": 16, "summary": "Lucien e Xarion incontrano Marcus e Dregan. Il gruppo prende forma nella taverna di Sable.", "dialogue": [{"speaker": "Lucien", "kind": "CANONICO", "text": "Finalmente un posto dove bere!"}, {"speaker": "Dregan", "kind": "CANONICO", "text": "Dregan e basta? Il mio cognome lo avevo… poi un giorno ricevetti un pugno così forte e me lo scordai."}], "cast": ["lucien", "xarion", "marcus", "dregan"], "canon": "Riassunto 19/06/2026"}, {"id": "c4-promiscuous", "chapter": "C4", "title": "Promiscuous Mode", "place": "Nostromo", "image": "assets/ships/nostromo_plan.png", "duration": 18, "summary": "Lucien ricostruisce la rete di Kethara e trasmette un falso proclama dell’Occhio del Creatore, nominando Vael suo araldo.", "dialogue": [{"speaker": "Lucien / broadcast", "kind": "CANONICO", "text": "Discepoli di Kethara! Parlo a voi attraverso i poteri dell'Era Atomica!"}, {"speaker": "Voce sconosciuta", "kind": "CANONICO", "text": "Devi vivere questa storia."}], "cast": ["lucien"], "canon": "C4 - Promiscuous Mode"}, {"id": "now-vael", "chapter": "ORA", "title": "Il conto arriva a Vael", "place": "Nostromo", "image": "assets/characters/vael.jpg", "duration": 15, "summary": "Vael affronta Lucien sulle conseguenze del falso messaggio: scisma, purghe e accuse opportunistiche possono trasformare chiunque gli sia vicino in un bersaglio.", "dialogue": [{"speaker": "Vael", "kind": "CANONICO", "text": "Questo è l’unico motivo per cui ti starò accanto fino alla fine dei nostri giorni. Dopo quello che hai fatto, non saranno poi molti."}], "cast": ["lucien", "vael"], "canon": "Riassunto"}, {"id": "now-abbordaggio", "chapter": "ORA", "title": "Abbording della Nostromo", "place": "Nostromo", "image": "assets/ships/nostromo_plan.png", "duration": 18, "summary": "Una spelljammer dei Figli dell’Orizzonte attracca. Il gruppo usa porte e corridoi della Nostromo per preparare un’imboscata.", "dialogue": [{"speaker": "Lucien / PA", "kind": "CANONICO", "text": "Siete entrati nel tempio di Vael, araldo dell’occhio del creatore. Deponete le armi e avvicinatevi alla sua guida."}], "cast": ["lucien", "xarion", "dregan", "marcus", "vael", "loox"], "canon": "Riassunto"}, {"id": "now-resheph", "chapter": "ORA", "title": "Resheph e nave catturata", "place": "Nostromo", "image": "assets/ships/nostromo_plan.png", "duration": 14, "summary": "Il capitano nemico viene ucciso, tre Fratelli si arrendono. Lucien accede ai droni Resheph e falsifica il rientro della nave catturata verso Kethara.", "dialogue": [], "cast": ["lucien", "dregan"], "canon": "Riassunto"}];
