window.THRANTIR_DATA.characters = [{"id": "lucien", "name": "Lucien Vhaar", "type": "PG", "image": "assets/characters/lucien_thrantir.png", "subtitle": "Bardo • Oceano", "tags": ["Party", "PG", "Oceano"], "text": "Veleggiante originario di Oceano. Musicista, recuperatore di DAM e improvvisato tecnico dell’Era Atomica. Sopravvissuto alla distruzione del proprio mondo e allo schianto su Thrantir.", "status": "A bordo della Nostromo. Ultima azione documentata: prepararsi a ripulire il sistema della spelljammer catturata per cancellare i legami con Kethara.", "known": "Canonico: Background + Riassunto + documenti personali."}, {"id": "xarion", "name": "Xarion Reed", "type": "PG", "image": "assets/characters/xarion.jpg", "subtitle": "Compagno • navigatore/tecnico", "tags": ["Party", "PG"], "text": "Compagno di Lucien fin dall’atterraggio su Thrantir. Ha interagito profondamente con l’elmo della Nostromo, arrivando a percepire segnali e navi attraverso di essa.", "status": "Sulla Nostromo. Ha individuato due droni Resheph e una spelljammer dei Figli dell’Orizzonte in avvicinamento.", "known": "Canonico dal Riassunto."}, {"id": "dregan", "name": "Dregan", "type": "PG", "image": "assets/characters/dregan.jpg", "subtitle": "Compagno • tattico", "tags": ["Party", "PG"], "text": "Membro del gruppo, pragmatico e incline a soluzioni dirette. Ha proposto di trasformare la Nostromo in un labirinto controllato durante l’abbordaggio.", "status": "Ha ucciso il capitano nemico durante l’imboscata e negoziato la resa dei tre superstiti.", "known": "Canonico dal Riassunto."}, {"id": "marcus", "name": "Marcus Shamrock", "type": "PG", "image": "assets/characters/marcus.jpg", "subtitle": "Compagno • legame con Otto", "tags": ["Party", "PG"], "text": "Membro del gruppo. Ha rivelato il proprio rapporto con un baatezu che chiama Otto von Sieg Hail, legato alle coordinate sull’Oron Esgail.", "status": "Sulla Nostromo.", "known": "Canonico dal Riassunto."}, {"id": "vael", "name": "Fratello Vael", "type": "NPC", "image": "assets/characters/vael.jpg", "subtitle": "Figura religiosa • Figli dell’Orizzonte", "tags": ["NPC", "Figli dell’Orizzonte"], "text": "Figura centrale nel rapporto del gruppo con i Figli dell’Orizzonte. Lucien lo ha proclamato, senza consenso, araldo dell’Occhio del Creatore durante l’incursione nelle reti di Kethara.", "status": "Ha avvertito Lucien che il falso messaggio potrebbe causare scisma, purghe e condanne, rendendo chiunque gli sia vicino un bersaglio prioritario.", "known": "Canonico dal Riassunto."}, {"id": "loox", "name": "Loox", "type": "NPC", "image": "assets/characters/loox.png", "subtitle": "Alleato • “araldo” scenico", "tags": ["NPC", "Alleato"], "text": "Creatura/alleato usato da Lucien durante l’abbordaggio come manifestazione scenica dell’autorità di Vael e dell’Occhio del Creatore.", "status": "Presente sulla Nostromo durante l’imboscata.", "known": "Canonico dal Riassunto; reference AI Art."}];


